        <router-link v-for="item in siteIndexItems" :key="item.route" :to="item.route" data-story-reveal>
          <span>{{ item.label }}</span>
        </router-link>
      </nav>
    </section>

    <Teleport to="body">
      <Transition name="home-preview-fade">
        <div v-if="sourcePreview" :key="sourcePreview.id" class="home-ask-preview" :style="previewStyle" aria-hidden="true">
          <span class="home-ask-preview-kicker">{{ sourcePreview.page }} › {{ sourcePreview.title }}</span>
          <p class="home-ask-preview-text">{{ sourcePreview.snippet }}</p>
        </div>
      </Transition>
    </Teleport>
