</template>

<script>
import AskViewOffer from './ui/AskViewOffer.vue';
import ViewComposeProgress from './view/ViewComposeProgress.vue';
import { isViewComposing, viewComposeState } from '../utils/viewSite.js';
import { loadHomeAskSnapshot, saveHomeAskSnapshot, prepareAskSourceReturn, consumeAskSourceDeparture } from '../utils/askReturn.js';
import { watchDesktopHover } from '../utils/desktopHover';
import { askConfigured, askErrorMessage, askStream } from '../utils/askSite';
import {
  allAskContexts,
  askAnswerFollowUps,
  askViewOffer,
  askViewRouting,
  groundAskFollowUps,
  looksLikeViewBuildRequest,
  askResponseIsComplete,
  citedSourcesFromAnswer,
  cleanAskAnswer,
  cleanAskContextText,
  diversifyAskWritingContexts,
  sourceDisplayTitle,
} from '../utils/askRetrieval';
import { askActionsForDisplay, renderAskAnswerLinks } from '../utils/askActions';
import { newAskContext } from '../utils/askTelemetry';
import { addAskTurn, askSourceIdsInRecent, loadAskSession } from '../utils/askSession';
import { cancelAnchorLanding, settleScrollToId } from '../utils/anchorLanding';
import AskAnswerAudio from './ui/AskAnswerAudio.vue';
import AskActions from './ui/AskActions.vue';
import ArrowUpRightIcon from './ui/ArrowUpRightIcon.vue';
import AiAskTerm from './ui/AiAskTerm.vue';
import HomeCreed from './ui/HomeCreed.vue';
import HomeWelcomeAudio from './ui/HomeWelcomeAudio.vue';
import EmbeddingMap from './EmbeddingMap.vue';
import { semanticTopK } from '../utils/semanticSearch';
import { animate } from 'motion';
import AboutTab from './AboutTab.vue';
import { initHomeStoryMotion } from '../utils/homeStoryMotion';
import { initHomeScene } from '../utils/homeScene';

export default {
  name: 'HomeConceptPage',
  components: { ViewComposeProgress, AskViewOffer, ArrowUpRightIcon, AskActions, AskAnswerAudio, AiAskTerm, HomeCreed, HomeWelcomeAudio, AboutTab, EmbeddingMap },
  data() {
    return {
      mobileViewport: false,
      desktopHover: false,
      askOpen: false,
      askInputActive: false,
      askTurn: 0,
      askText: '',
      submittedQuestion: '',
      askAnswer: '',
      askSources: [],
      askBusy: false,
      askError: '',
      askComposing: false,
      sceneMasked: false,
      sceneMuted: true,
      viewRouting: 'none',
      homeViewError: '',
      groundedFollowUps: null,
      askMapVisible: false,
      askMapHits: [],
      askMapLabel: '',
      askMapFinalized: false,
      hoveredSourceId: null,
      previewStyle: null,
      activeChapter: 'story-hello',
      siteIndexItems: [
        { label: 'Study', route: '/education' },
        { label: 'Work', route: '/experience' },
        { label: 'Research', route: '/research' },
        { label: 'Builds', route: '/projects' },
        { label: 'Fragments', route: '/fragments' },
        { label: 'Views', route: '/views' },
      ],
      chapters: [
        { id: 'story-hello', label: 'Hello' },
        { id: 'story-now', label: 'Now' },
        { id: 'story-about', label: 'About' },
        { id: 'story-research', label: 'Research' },
        { id: 'story-builds', label: 'Builds' },
        { id: 'story-life', label: 'Life' },
        { id: 'story-contact', label: 'Contact' },
        { id: 'story-index', label: 'Index' },
      ],
      ...(loadHomeAskSnapshot()?.state || {}),
    };
  },
  computed: {
    engaged() { return this.askOpen; },
    homeViewBusy() { return viewComposeState.active && viewComposeState.surface === 'home' && viewComposeState.label === this.submittedQuestion; },
    homeViewStartedAt() { return viewComposeState.startedAt; },
    askInputLocked() { return this.askBusy || isViewComposing(); },
    askAnswerText() { return cleanAskAnswer(this.askAnswer); },
    askAnswerHtml() { return renderAskAnswerLinks(this.askAnswerText); },
    askActionsList() { return askActionsForDisplay(this.askAnswer, this.viewRouting); },
    askErrorText() { return askErrorMessage(); },
    citedSources() {
      const seen = new Set();
      return citedSourcesFromAnswer(this.askAnswer, this.askSources).filter(source => {
        const key = `${source.route}#${source.anchor || ''}`;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      }).map(source => ({ ...source, title: sourceDisplayTitle(source) }));
    },
    followUps() { return this.groundedFollowUps ?? askAnswerFollowUps(this.askAnswer).slice(0, 3); },
            sourcePreview() {
                if (!this.desktopHover || !this.hoveredSourceId) return null;
                const s = this.citedSources.find((x) => x.id === this.hoveredSourceId);
                if (!s) return null;
                const text = cleanAskContextText(s.body || '').replace(/\s+/g, ' ').trim();
                const snippet = text
                    ? (text.length > 230 ? `${text.slice(0, 230).trim()}…` : text)
                    : 'Open the passage to read it.';
                return { id: s.id, page: s.page, title: s.title, snippet };
            },
    viewOffer() { return askViewOffer(this.askAnswer); },
  },
  watch: {
    hoveredSourceId(id) { this.positionSourcePreview(id); },
  },
  mounted() {
    this._onHomeViewError = event => { this.homeViewError = String(event.detail?.message || 'Please try again.'); };
    window.addEventListener('home-view-error', this._onHomeViewError);
    this.restoreAnswerPosition();
    this._stopHover = watchDesktopHover(enabled => { this.desktopHover = enabled; if (!enabled) this.hoveredSourceId = null; });
    this._dismissSourcePreview = () => { this.hoveredSourceId = null; };
    window.addEventListener('scroll', this._dismissSourcePreview, { capture: true, passive: true });
    this._askSequence = 0;
    this._mobileQuery = window.matchMedia('(max-width: 760px)');
    this._updateMobile = () => {
      this.mobileViewport = this._mobileQuery.matches;
      if (this.mobileViewport && this.$refs.sceneVideo) {
        this.$refs.sceneVideo.muted = true;
        this.sceneMuted = true;
      }
      this.$nextTick(() => this.syncMobileHeroLayout());
    };
    this._updateMobile();
    this._mobileQuery.addEventListener('change', this._updateMobile);
    this.$nextTick(() => {
      this._stopStoryMotion = initHomeStoryMotion(this.$el, (id) => { this.activeChapter = id; });
      this._heroResize = new ResizeObserver(() => {
        cancelAnimationFrame(this._heroLayoutFrame);
        this._heroLayoutFrame = requestAnimationFrame(() => this.syncMobileHeroLayout());
      });
      ['.concept-mobile-identity', '.concept-mobile-identity h1', '.concept-mobile-identity .concept-credo', '.concept-mobile-identity .concept-context'].forEach(selector => {
        this._heroResize.observe(this.$el.querySelector(selector), { box: 'border-box' });
      });
      this.syncMobileHeroLayout();
      const header = document.querySelector('.container > .header');
      this._syncChapterViewport = () => {
        const fixed = header && ['fixed', 'sticky'].includes(window.getComputedStyle(header).position);
        const inset = fixed ? Math.max(0, header.getBoundingClientRect().bottom) : 0;
        this.$el.style.setProperty('--story-top', `${inset}px`);
      };
      this._syncChapterViewport();
      window.addEventListener('resize', this._syncChapterViewport);
      if (header) {
        this._chapterHeaderResize = new ResizeObserver(this._syncChapterViewport);
        this._chapterHeaderResize.observe(header);
      }
      const footer = document.querySelector('.container > .footer');
      if (footer) {
        this._footerResize = new ResizeObserver(() => {
          const style = window.getComputedStyle(footer);
          const space = footer.offsetHeight + (parseFloat(style.marginTop) || 0) + (parseFloat(style.marginBottom) || 0);
          this.$el.style.setProperty('--story-footer-space', `${space}px`);
        });
        this._footerResize.observe(footer, { box: 'border-box' });
      }
    });
    this._reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
    this._onMotionChange = () => {
      if (this._reducedMotion.matches) this.$refs.sceneVideo?.pause();
    };
    this._reducedMotion.addEventListener('change', this._onMotionChange);
    this._stopScene = initHomeScene(this.$refs.sceneVideo, {
      onMask: active => { this.sceneMasked = active; },
      canPlay: () => {
        const bounds = this.$refs.sceneVideo.getBoundingClientRect();
        return !document.hidden && !this._reducedMotion.matches && bounds.bottom > 0 && bounds.top < window.innerHeight;
      },
    });
    if (!this._reducedMotion.matches) this.$refs.sceneVideo?.play().catch(() => {});
  },
  beforeRouteLeave() {
    this.saveAnswerPosition();
  },
  beforeUnmount() {
    window.removeEventListener('home-view-error', this._onHomeViewError);
    this._stopHover?.();
    // Teleport removes the mobile Ask contents before the page fade finishes.
    // Reserve their height until the outgoing homepage itself is removed.
    const mobileAsk = this.$el.querySelector('#story-mobile-ask');
    if (this.mobileViewport && mobileAsk) mobileAsk.style.minHeight = `${mobileAsk.getBoundingClientRect().height}px`;
    this._askSequence += 1;
    window.removeEventListener('scroll', this._dismissSourcePreview, { capture: true });
    this._homeAnims?.forEach(animation => animation.stop());
    this._stopStoryMotion?.();
    this._stopChapterScroll?.();
    this._stopScene?.();
    this._heroResize?.disconnect();
    this._footerResize?.disconnect();
    this._chapterHeaderResize?.disconnect();
    window.removeEventListener('resize', this._syncChapterViewport);
    cancelAnimationFrame(this._heroLayoutFrame);
    this._mobileQuery?.removeEventListener('change', this._updateMobile);
    this._reducedMotion?.removeEventListener('change', this._onMotionChange);
  },
  methods: {
            positionSourcePreview(id) {
                if (!id) {
                    this.previewStyle = null;
                    return;
                }
                this.$nextTick(() => {
                    const wrap = this.$el && this.$el.querySelector('.concept-answer-sources-wrap');
                    const chip = wrap && wrap.querySelector(`.concept-answer-source[data-source-key="${id}"]`);
                    const preview = document.querySelector('.home-ask-preview');
                    if (!wrap || !chip || !preview) return;
                    const cr = chip.getBoundingClientRect();
                    const gap = 8;
                    const width = Math.max(200, Math.min(340, window.innerWidth - 24));
                    const left = Math.max(12, Math.min(cr.left, window.innerWidth - width - 12));
                    const height = preview.offsetHeight || 150;
                    const vh = window.innerHeight;
                    let top;
                    if (cr.bottom + gap + height <= vh - 8) {
                        top = cr.bottom + gap;
                    } else if (cr.top - gap - height >= 8) {
                        top = cr.top - gap - height;
                    } else {
                        top = Math.max(8, vh - height - 8);
                    }
                    this.previewStyle = {
                        left: `${left}px`,
                        top: `${top}px`,
                        width: `${width}px`,
                    };
                });
            },
            beforeHomeChipEnter(el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(4px)';
            },
            enterHomeChip(el, done) {
                if (this.homeReduceMotion()) {
                    el.style.opacity = '';
                    el.style.transform = '';
                    done();
                    return;
                }
                const index = Math.max(0, Array.from(el.parentNode ? el.parentNode.children : []).indexOf(el));
                let settled = false;
                const finish = () => {
                    if (settled) return;
                    settled = true;
                    el.style.opacity = '';
                    el.style.transform = '';
                    this.untrackHomeAnim(animation);
                    done();
                };
                const animation = this.trackHomeAnim(animate(el, {
                    opacity: [0, 1],
                    transform: ['translateY(4px)', 'translateY(0px)'],
                }, {
                    type: 'spring',
                    bounce: 0,
                    duration: 0.3,
                    delay: index * 0.045,
                    onComplete: finish,
                }));
                window.setTimeout(finish, 1000);
            },
            leaveHomeChip(el, done) {
                if (this.homeReduceMotion()) {
                    done();
                    return;
                }
                let settled = false;
                const finish = () => {
                    if (settled) return;
                    settled = true;
                    this.untrackHomeAnim(animation);
                    done();
                };
                const animation = this.trackHomeAnim(animate(el, {
                    opacity: [1, 0],
                    transform: ['translateY(0px)', 'translateY(-2px)'],
                }, {
                    type: 'spring',
                    bounce: 0,
                    duration: 0.12,
                    onComplete: finish,
                }));
                window.setTimeout(finish, 400);
            },
    homeReduceMotion() { return this._reducedMotion?.matches; },
    trackHomeAnim(animation) { (this._homeAnims ||= new Set()).add(animation); return animation; },
    untrackHomeAnim(animation) { this._homeAnims?.delete(animation); },
            async prepareHomeAskMap(question, seq) {
                try {
                    const hits = await semanticTopK(question, 8);
                    if (seq !== this._askSequence || this.askMapFinalized) return;
                    this.askMapHits = hits.map((h) => ({ id: h.id, score: h.score }));
                    this.askMapLabel = question;
                    const map = this.$refs.homeAskMap;
                    if (map && map.showExternalHits) {
                        // While waiting for the answer: keep the full map in view and just
                        // light up the retrieved passages, no zoom-in yet.
                        map.showExternalHits(this.askMapHits, {
                            label: question,
                            focus: false,
                            keepCentered: false,
                            duration: 900,
                        });
                    }
                } catch (err) {
                    console.warn('home ask map failed:', err);
                }
            },
            citedSourceItems() {
                const cited = new Set();
                const re = /\[([\d,\s]+)\]/g;
                let m;
                while ((m = re.exec(this.askAnswer))) {
                    m[1].split(/[\s,]+/).filter(Boolean).forEach((n) => cited.add(parseInt(n, 10)));
                }
                return this.askSources.filter((source, i) => cited.has(i + 1) && source && source.id != null);
            },
            finishHomeAskMap() {
                const hits = this.citedSourceItems().map((source) => ({ id: source.id, score: 0.92 }));
                this.askMapHits = hits;
                this.askMapLabel = hits.length ? 'cited passages' : this.askMapLabel;
                this.askMapFinalized = true;
                const map = this.$refs.homeAskMap;
                if (!map || !map.showExternalHits) return;
                // Answer is in: zoom in onto the cited passages. (With no citations the
                // hit list is empty and the map falls back to the full view.)
                map.showExternalHits(hits, {
                    label: this.askMapLabel,
                    focus: true,
                    keepCentered: true,
                    duration: 850,
                });
            },
            syncHomeAskMap() {
                const map = this.$refs.homeAskMap;
                if (!map || !map.showExternalHits || !this.askMapHits.length) return;
                map.showExternalHits(this.askMapHits, {
                    label: this.askMapLabel,
                    // Full map until the answer is finalized, then focus on the cited passages.
                    focus: this.askMapFinalized,
                    keepCentered: this.askMapFinalized,
                    duration: 500,
                });
            },
    muteSceneForWelcome() {
      if (this.$refs.sceneVideo) this.$refs.sceneVideo.muted = true;
      this.sceneMuted = true;
    },
    syncSceneSound() {
      this.sceneMuted = this.$refs.sceneVideo.muted;
    },
    toggleSceneSound() {
      const video = this.$refs.sceneVideo;
      if (!video || this.mobileViewport) return;
      video.muted = !video.muted;
      this.sceneMuted = video.muted;
      if (!video.muted) window.dispatchEvent(new CustomEvent('view-summary-play', { detail: this }));
    },
    createViewFromAnswer() {
      if (!this.submittedQuestion || isViewComposing()) return;
      this.askOpen = true;
      this.homeViewError = '';
      this.saveAnswerPosition();
      window.dispatchEvent(new CustomEvent('open-site-view', {
        detail: { question: this.submittedQuestion, compose: true, askOfferConfirmed: true, surface: 'home' },
      }));
    },
    async groundFollowUps(sequence) {
      const questions = askAnswerFollowUps(this.askAnswer).slice(0, 3);
      const grounded = await groundAskFollowUps(questions);
      if (sequence === this._askSequence) this.groundedFollowUps = grounded;
    },
    goChapter(id) {
      const target = this.$el.querySelector(`#${id}`);
      if (!target) return;
      cancelAnchorLanding();
      this._stopChapterScroll?.();
      this._syncChapterViewport?.();
      const destination = () => {
        if (id === 'story-hello') return 0;
        const inset = parseFloat(window.getComputedStyle(this.$el).getPropertyValue('--story-top')) || 0;
        const divider = parseFloat(window.getComputedStyle(target).borderTopWidth) || 0;
        // Land inside the chapter, past its separator. Round upward so a
        // fractional document coordinate cannot leave a sliver of the line.
        return Math.max(0, Math.ceil(window.scrollY + target.getBoundingClientRect().top + divider - inset));
      };
      if (this._reducedMotion?.matches) {
        window.scrollTo({ top: destination(), behavior: 'instant' });
        return;
      }
      const start = window.scrollY;
      const duration = Math.min(600, Math.max(360, Math.abs(destination() - start) * .12));
      let frame;
      let started;
      const stop = () => {
        cancelAnimationFrame(frame);
        ['wheel', 'touchstart', 'pointerdown', 'keydown'].forEach(type => window.removeEventListener(type, stop));
        if (this._stopChapterScroll === stop) this._stopChapterScroll = null;
      };
      this._stopChapterScroll = stop;
      ['wheel', 'touchstart', 'pointerdown', 'keydown'].forEach(type => window.addEventListener(type, stop, { passive: true }));
      const step = time => {
        if (started === undefined) started = time;
        const progress = Math.min(1, (time - started) / duration);
        const end = destination();
        window.scrollTo({ top: progress === 1 ? end : start + (end - start) * (1 - Math.pow(1 - progress, 3)), behavior: 'instant' });
        if (progress < 1) frame = requestAnimationFrame(step);
        else stop();
      };
      frame = requestAnimationFrame(step);
    },
    syncMobileHeroLayout() {
      if (!this.mobileViewport) return;
      const panel = this.$el.querySelector('.concept-mobile-identity');
      const title = panel?.querySelector('h1');
      const subtitle = panel?.querySelector('.concept-credo');
      const affiliations = panel?.querySelector('.concept-context');
      if (!title || !subtitle || !affiliations) return;
      const subtitleStyle = window.getComputedStyle(subtitle);
      const titleHeight = title.offsetHeight;
      const subtitleHeight = parseFloat(subtitleStyle.lineHeight) * 3;
      const subtitleMargin = parseFloat(subtitleStyle.marginTop) || 0;
      const sceneHeight = affiliations.offsetHeight;
      if (!titleHeight || !subtitleHeight || !sceneHeight) return;
      // Match IndexPage's 1 : 1.2 : 1 distribution of the remaining height.
      // Layout sizes remain stable while the entrance transform is animating.
      const gap = Math.max(20, (panel.offsetHeight - titleHeight - subtitleMargin - subtitleHeight - sceneHeight) / 3.2);
      panel.style.setProperty('--hero-gap', `${Math.round(gap)}px`);
      panel.style.setProperty('--hero-scene-height', `${sceneHeight}px`);
    },
    focusAskInput() {
      this.$refs.askInput?.focus();
    },
    keepMobileAskFocus(event) {
      // Keep the send target still until the tap submits the question.
      if (this.mobileViewport) event.preventDefault();
    },
    submitAsk() {
      if (this.askComposing) return;
      const question = this.askText.trim();
      if (!question || this.askInputLocked) return;
      this.runAsk(question);
    },
    askFollowUp(question) {
      this.runAsk(question);
      if (!this.mobileViewport) this.$nextTick(() => this.$refs.askInput?.focus());
    },
    resetAsk() {
      saveHomeAskSnapshot(null);
      this._askSequence += 1;
      this.askText = '';
      // Keep the outgoing answer mounted while the card returns to its introduction.
      this.askOpen = false;
      this.askBusy = false;
      this.askMapVisible = false;
      this.hoveredSourceId = null;
      this.$nextTick(() => this.$refs.askInput?.focus());
    },
    async runAsk(question) {
      if (isViewComposing()) return;
      if (looksLikeViewBuildRequest(question)) {
        this.askAnswer = '';
        this.askSources = [];
        this.submittedQuestion = question;
        this.createViewFromAnswer();
        return;
      }
      const sequence = ++this._askSequence;
      const telemetry = newAskContext('home');
      if (this.mobileViewport) this.$refs.askInput?.blur();
      this.askInputActive = false;
      this.askOpen = true;
      this.askTurn += 1;
      this.submittedQuestion = question;
      this.askText = '';
      this.askAnswer = '';
      this.askSources = [];
      this.askError = '';
      this.viewRouting = 'none';
      this.groundedFollowUps = null;
      this.askMapVisible = true;
      this.askMapHits = [];
      this.askMapLabel = question;
      this.askMapFinalized = false;
      this.hoveredSourceId = null;
      this.askBusy = true;
      this.$nextTick(() => this.prepareHomeAskMap(question, sequence));
      this.$nextTick(() => {
        if (this.$refs.answerScroll) this.$refs.answerScroll.scrollTop = 0;
      });
      try {
        if (!askConfigured()) throw new Error('ask unavailable');
        const recentSourceIds = askSourceIdsInRecent(loadAskSession(), 18);
        const contexts = diversifyAskWritingContexts(await allAskContexts(question), question, telemetry.event_id, recentSourceIds);
        if (sequence !== this._askSequence) return;
        this.askSources = contexts;
        const payload = contexts.map((context) => ({
          page: context.page,
          title: sourceDisplayTitle(context),
          text: cleanAskContextText(context.body),
          source_id: context.source_id || context.chunk_id || String(context.id || ''),
        }));
        const stream = askStream(question, payload, {
          meta: {
            event_id: telemetry.event_id,
            session_id: telemetry.session_id,
            turn_index: telemetry.turn_index,
            surface: telemetry.surface,
            recent_source_ids: recentSourceIds,
          },
        });
        let answer = '';
        for await (const token of stream) {
          if (sequence !== this._askSequence) return;
          answer += token;
          this.askAnswer = answer;
        }
        if (!askResponseIsComplete(answer)) throw new Error('incomplete ask response');
        if (sequence !== this._askSequence) return;
        this.viewRouting = askViewRouting(answer);
        addAskTurn(addAskTurn(loadAskSession(), {
          role: 'user', text: question, source_ids: [],
        }), {
          role: 'assistant', text: answer,
          source_ids: citedSourcesFromAnswer(answer, contexts).map(source => source.source_id).filter(Boolean),
        });
        this.finishHomeAskMap();
        if (this.viewRouting === 'build') this.createViewFromAnswer();
        this.groundFollowUps(sequence).catch(() => {});
      } catch (error) {
        if (sequence !== this._askSequence) return;
        console.error('home ask failed:', error);
        this.askAnswer = '';
        this.askSources = [];
        this.askError = String(error?.message || error);
      } finally {
        if (sequence === this._askSequence) this.askBusy = false;
      }
    },
    saveAnswerPosition() {
      if (!this.askOpen || !this.askAnswer || this.askBusy) return;
      const state = {};
      for (const key of ['askOpen', 'askTurn', 'askText', 'submittedQuestion', 'askAnswer', 'askSources', 'askError', 'viewRouting', 'groundedFollowUps', 'askMapVisible', 'askMapHits', 'askMapLabel', 'askMapFinalized']) state[key] = this[key];
      saveHomeAskSnapshot({ state, answerTop: this.$refs.answerScroll?.scrollTop || 0, pageY: window.scrollY });
    },
    restoreAnswerPosition() {
      const snapshot = loadHomeAskSnapshot();
      if (!snapshot) return;
      Object.assign(this, snapshot.state);
      this.$nextTick(() => {
        if (this.$refs.answerScroll) this.$refs.answerScroll.scrollTop = snapshot.answerTop;
        this.syncHomeAskMap();
      });
    },
    rememberAnswerNavigation(event) {
      if (event.target.closest('.ask-inline-link, .ask-action[data-ask-navigate]')) this.rememberSourceReturn();
    },
    rememberSourceReturn() {
      this.saveAnswerPosition();
      prepareAskSourceReturn({ route: this.$route.fullPath, label: 'Ask', scrollY: window.scrollY,
        askReturn: { surface: 'home' } });
    },
    goSource(source) {
      this.hoveredSourceId = null;
      if (!source?.route) return;
      this.rememberSourceReturn();
      if (this.$route.path !== source.route) {
        const target = { path: source.route };
        if (source.anchor) target.hash = `#${source.anchor}`;
        this.$router.push(target).catch(() => {});
        return;
      }
      consumeAskSourceDeparture();
      if (source.anchor) settleScrollToId(source.anchor);
    },
  },
};
